select jsonb_build_object('role',current_user,'superuser',(select rolsuper from pg_roles where rolname=current_user),'admin_usage',pg_has_role(current_user,'supabase_admin','USAGE'),'auth_schema_usage',has_schema_privilege(current_user,'auth','USAGE'),'auth_schema_create',has_schema_privilege(current_user,'auth','CREATE'),'net_owner_usage',case when to_regclass('net._http_response')is not null then pg_has_role(current_user,(select relowner from pg_class where oid='net._http_response'::regclass),'USAGE')else null end);
